using UnityEngine; using UnityEngine.UI; using UnityEngine.EventSystems;
namespace Blockverse {
 public sealed class PieceDragView:MonoBehaviour,IBeginDragHandler,IDragHandler,IEndDragHandler {
  public PieceDefinition Definition{get;private set;} private GameController controller;private Canvas canvas;private CanvasGroup group;private Transform originalParent;private Vector2 originalPosition;private Color currentTint;
  public void Initialize(GameController owner,PieceDefinition definition,RectTransform tray){controller=owner;Definition=definition;canvas=GetComponentInParent<Canvas>();group=gameObject.AddComponent<CanvasGroup>();var hit=GetComponent<Image>();if(hit==null)hit=gameObject.AddComponent<Image>();hit.color=new Color(1,1,1,.01f);hit.raycastTarget=true;BuildVisual();}
  public void RefreshTheme(){currentTint=GetTint();foreach(Transform child in transform){var image=child.GetComponent<Image>();if(image!=null)image.color=currentTint;}}
  private Color GetTint(){if(Definition.Special==SpecialPieceType.Bomb)return new Color(1,.38f,.28f);if(Definition.Special==SpecialPieceType.Rainbow)return new Color(.75f,.42f,1);if(Definition.Special==SpecialPieceType.Lightning)return new Color(1,.82f,.25f);switch(PlayerPrefs.GetInt("blockverse_theme",0)){case 1:return new Color(1f,.43f,.22f);case 2:return new Color(.3f,.82f,.52f);case 3:return new Color(.72f,.48f,1f);default:return new Color(.28f,.68f,1f);}}
  private void BuildVisual(){bool[,] s=Definition.Shape;int rows=s.GetLength(0),cols=s.GetLength(1);var rect=(RectTransform)transform;rect.sizeDelta=new Vector2(150,130);float size=Mathf.Min(30,88f/Mathf.Max(rows,cols)),w=cols*size+(cols-1)*4,h=rows*size+(rows-1)*4;Color tint=GetTint();currentTint=tint;for(int y=0;y<rows;y++)for(int x=0;x<cols;x++){if(!s[y,x])continue;var cell=new GameObject("PieceCell",typeof(RectTransform),typeof(Image));cell.transform.SetParent(transform,false);var r=cell.GetComponent<RectTransform>();r.sizeDelta=new Vector2(size,size);r.anchoredPosition=new Vector2(-w/2+size/2+x*(size+4),h/2-size/2-y*(size+4));var img=cell.GetComponent<Image>();img.color=tint;img.raycastTarget=false;}}
  public void OnBeginDrag(PointerEventData e){if(!enabled||canvas==null)return;originalParent=transform.parent;originalPosition=((RectTransform)transform).anchoredPosition;transform.SetParent(canvas.transform,true);group.blocksRaycasts=false;group.alpha=.88f;transform.position=e.position;}
  public void OnDrag(PointerEventData e){if(enabled)transform.position=e.position;}
  public void OnEndDrag(PointerEventData e){if(originalParent==null)return;bool placed=controller.TryDrop(Definition,e.position,e.pressEventCamera);transform.SetParent(originalParent,false);((RectTransform)transform).anchoredPosition=originalPosition;group.blocksRaycasts=true;group.alpha=1;if(placed)controller.ConsumePiece(this);}
 }
}